ALTER TABLE partner_campaigns ADD COLUMN resource_id CHAR(36) NULL, ADD INDEX idx_partner_campaign_resource (resource_id);

ALTER TABLE resources ADD COLUMN workspace_id CHAR(36) NULL, ADD COLUMN relationship_type VARCHAR(40) NOT NULL DEFAULT 'OWNED', ADD COLUMN provider_name VARCHAR(190) NULL, ADD COLUMN campaign_id CHAR(36) NULL, ADD INDEX idx_resources_workspace (workspace_id), ADD INDEX idx_resources_campaign (campaign_id);

CREATE TABLE lead_attributions (id CHAR(36) NOT NULL, workspace_id CHAR(36) NOT NULL, lead_id CHAR(36) NOT NULL, attribution_type VARCHAR(40) NOT NULL, source VARCHAR(100) NULL, medium VARCHAR(100) NULL, campaign VARCHAR(150) NULL, content VARCHAR(190) NULL, term VARCHAR(190) NULL, referral_code VARCHAR(100) NULL, referral_link_id CHAR(36) NULL, partner_id CHAR(36) NULL, campaign_id CHAR(36) NULL, product_id CHAR(36) NULL, resource_id CHAR(36) NULL, is_first_touch BOOLEAN NOT NULL DEFAULT TRUE, is_last_touch BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(0) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), INDEX idx_lead_attr_lead (lead_id, created_at), INDEX idx_lead_attr_workspace (workspace_id, created_at), INDEX idx_lead_attr_partner (partner_id), INDEX idx_lead_attr_campaign (campaign_id), INDEX idx_lead_attr_source (source, medium, campaign), CONSTRAINT fk_lead_attr_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT, CONSTRAINT fk_lead_attr_lead FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE, CONSTRAINT fk_lead_attr_referral FOREIGN KEY (referral_link_id) REFERENCES referral_links(id) ON DELETE SET NULL, CONSTRAINT fk_lead_attr_partner FOREIGN KEY (partner_id) REFERENCES partners(id) ON DELETE SET NULL, CONSTRAINT fk_lead_attr_campaign FOREIGN KEY (campaign_id) REFERENCES partner_campaigns(id) ON DELETE SET NULL, CONSTRAINT fk_lead_attr_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL, CONSTRAINT fk_lead_attr_resource FOREIGN KEY (resource_id) REFERENCES resources(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE social_profiles (id CHAR(36) NOT NULL, workspace_id CHAR(36) NOT NULL, platform VARCHAR(40) NOT NULL, label VARCHAR(80) NOT NULL, url VARCHAR(1000) NOT NULL, handle VARCHAR(190) NULL, display_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(0) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_social_profile_workspace_platform (workspace_id, platform), INDEX idx_social_profile_workspace_active (workspace_id, is_active, display_order), CONSTRAINT fk_social_profile_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE resource_attributions (id CHAR(36) NOT NULL, resource_request_id CHAR(36) NOT NULL, workspace_id CHAR(36) NOT NULL, referral_code VARCHAR(100) NULL, referral_link_id CHAR(36) NULL, partner_id CHAR(36) NULL, campaign_id CHAR(36) NULL, source VARCHAR(100) NULL, medium VARCHAR(100) NULL, campaign VARCHAR(150) NULL, content VARCHAR(190) NULL, created_at DATETIME(0) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), INDEX idx_resource_attr_request (resource_request_id), INDEX idx_resource_attr_partner (partner_id), INDEX idx_resource_attr_campaign (campaign_id), CONSTRAINT fk_resource_attr_request FOREIGN KEY (resource_request_id) REFERENCES resource_requests(id) ON DELETE CASCADE, CONSTRAINT fk_resource_attr_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT, CONSTRAINT fk_resource_attr_referral FOREIGN KEY (referral_link_id) REFERENCES referral_links(id) ON DELETE SET NULL, CONSTRAINT fk_resource_attr_partner FOREIGN KEY (partner_id) REFERENCES partners(id) ON DELETE SET NULL, CONSTRAINT fk_resource_attr_campaign FOREIGN KEY (campaign_id) REFERENCES partner_campaigns(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;